/* Surat agunan dan kendaraan: isian manual, tanpa data contoh nasabah. */
(() => {
'use strict';
const esc = value => String(value ?? '').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const meta=[['nomor','Nomor surat'],['tanggal','Tanggal surat','date'],['lampiran','Lampiran']];
const destination=[['tujuan','Kepada / instansi tujuan','textarea'],['kotaTujuan','Kota / wilayah tujuan']];
const settings=[['bank','Nama bank pada kop'],['cabang','Cabang pada kop'],['alamatKop','Alamat dan kontak pada kop','textarea'],['bankTtd','Nama bank pada tanda tangan'],['unitTtd','Unit / cabang penanda tangan'],['pejabat','Nama penanda tangan'],['jabatan','Jabatan penanda tangan']];
const certificate=[['jenisSertifikat','Jenis sertifikat'],['sertifikat','Nomor sertifikat'],['wilayahSertifikat','Desa / kelurahan pada nomor sertifikat'],['pemilik','Nama pemilik sertifikat']];
const definitions={
 htel:{title:'Permohonan Pendaftaran Hak Tanggungan (HTEL)',fields:[...meta,...destination,['nama','Nama debitur'],['peringkat','Peringkat hak tanggungan'],...certificate,['akta','Nomor Akta Pemberian Hak Tanggungan'],['tanggalAkta','Tanggal Akta Pemberian Hak Tanggungan','date'],...settings]},
 roya:{title:'Surat Permohonan Roya',fields:[...meta,...destination,...certificate,['lokasi','Letak tanah (blok, desa, kecamatan, kabupaten/kota)','textarea'],['peringkat','Peringkat hak tanggungan'],['ht','Nomor sertifikat hak tanggungan'],['tanggalHt','Tanggal sertifikat hak tanggungan','date'],...settings]},
 stnk:{title:'Surat Keterangan BPKB untuk Perpanjangan STNK',fields:[...meta,['bpkb','Nomor BPKB'],['nama','Nama dalam BPKB'],['alamat','Alamat dalam BPKB','textarea'],['rangka','Nomor rangka / NIK kendaraan'],['mesin','Nomor mesin'],['polisi','Nomor polisi dalam BPKB'],...settings]},
 angsuran:{title:'Surat Penyesuaian Angsuran',fields:[...meta,['tujuan','Kepada / unit tujuan','textarea'],['kotaTujuan','Lokasi tujuan'],['nota','Nomor nota restrukturisasi'],['tanggalNota','Tanggal nota restrukturisasi','date'],['nama','Nama debitur'],['rekening','Nomor rekening pinjaman'],['agf','Nomor rekening tabungan (AGF)'],['periode','Periode angsuran'],['pokok','Angsuran pokok (Rp)'],['bunga','Angsuran bunga (Rp)'],['tbyd','TBYD (Rp)'],['bydt','BYDT (Rp)'],['jumlah','Jumlah angsuran (Rp)'],...settings,['bankTtd2','Nama bank penanda tangan kedua'],['unitTtd2','Unit penanda tangan kedua'],['pejabat2','Nama penanda tangan kedua'],['jabatan2','Jabatan penanda tangan kedua']]}
};
const classic='Jl P. H. H. Mustofa No 39 Neglasari\nBandung\nTel. 022-7217861\nFax.022-7217863\nwww.bankmandiri.co.id';
const branch='Jl. PHH. Mustopa No. 39\nBandung 40124 Indonesia\nTelp. (62-22) 7217861\nFax. (62-22) 7217863\nwww.bankmandiri.co.id';
function defaults(type){return {
 bank:type==='htel'||type==='angsuran'?'PT Bank Mandiri (Persero) Tbk':'PT Bank Mandiri (Persero) Tbk.',
 cabang:type==='htel'||type==='angsuran'?'Cabang Bandung Jamsostek':'Branch Bandung Jamsostek',
 alamatKop:type==='htel'||type==='angsuran'?classic:branch,
 bankTtd:type==='htel'?'PT. Bank Mandiri (Persero) Tbk.':type==='angsuran'?'PT. Bank Mandiri (persero) Tbk':'PT Bank Mandiri (Persero) Tbk.',
 unitTtd:type==='angsuran'?'MBU Bandung Jamsostek 1':'Branch Bandung Jamsostek',
 pejabat:'Deki Elanda Pradikta',jabatan:type==='roya'?'Penyelia Unit':'Mikro Banking Manager',
 lampiran:type==='roya'?'2 (Dua) sertifikat':type==='angsuran'?'1 (satu) set':'-',
 ...(type==='htel'?{tujuan:'Kepala Kantor\nPertanahan Kabupaten Bandung',kotaTujuan:'Kabupaten Bandung',peringkat:'I (Pertama)',jenisSertifikat:'Hak Milik'}:{}),
 ...(type==='roya'?{tujuan:'Kepala Kantor\nBadan Pertanahan Nasional Kabupaten Bandung',kotaTujuan:'Kabupaten Bandung',peringkat:'I (Kesatu)',jenisSertifikat:'Hak Milik'}:{}),
 ...(type==='angsuran'?{tujuan:'PT. Bank Mandiri (Persero), Tbk.\nLoan Appraisal Maintenance and Posting Department',kotaTujuan:'Tempat',bankTtd2:'PT. Bank Mandiri (persero) Tbk',unitTtd2:'MBC Bandung Surapati',pejabat2:'Atika Fadillah',jabatan2:'Micro Banking Cluster Manager'}:{})
};}
const css=`
.mf-property{padding:20mm 24mm;font:10pt/1.35 Arial,sans-serif;min-height:296mm;overflow-wrap:anywhere}.mf-property p{margin:0 0 14px;text-align:justify}.mf-property-head{display:grid;grid-template-columns:minmax(0,1fr) 58mm;gap:8mm;min-height:49mm;margin-bottom:1mm}.mf-property-meta{padding-top:12mm;min-width:0}.mf-property-meta table{width:100%;border-collapse:collapse}.mf-property-meta td{padding:0;vertical-align:top}.mf-property-meta td:first-child{width:19mm}.mf-property-meta td:nth-child(2){width:4mm}.mf-property-brand{font:8pt/1.2 Arial;color:#17365d}.mf-property-brand img{display:block;width:58mm;height:auto;margin-bottom:3px}.mf-property-to{margin:0 0 17px;line-height:1.35}.mf-property-subject{display:grid;grid-template-columns:17mm 4mm minmax(0,1fr);gap:0;margin-bottom:18px;break-inside:avoid}.mf-property-subject>div:last-child{text-align:justify}.mf-property-list{padding-left:21px;margin:0 0 18px}.mf-property-list li{padding-left:4px;text-align:justify;margin-bottom:10px}.mf-property-ttd{margin-top:24px;break-inside:avoid;page-break-inside:avoid}.mf-property-ttd .mf-property-ink{height:23mm;display:flex;align-items:center}.mf-property-ink img{width:43mm;height:22mm;object-fit:contain;object-position:left center}.mf-property-title{font:bold 11pt Arial!important;text-decoration:underline;text-align:center!important;margin:0 0 24px!important}.mf-property-data{width:100%;border-collapse:collapse;margin:16px 0 23px}.mf-property-data td{vertical-align:top;padding:3px 0}.mf-property-data td:first-child{width:47mm}.mf-property-data td:nth-child(2){width:4mm}.mf-property-stnk{font-size:11pt}.mf-property-angsuran{font-size:11pt;padding:15mm 19mm}.mf-property-angsuran .mf-property-head{min-height:51mm}.mf-property-amounts{width:100%;table-layout:fixed;border-collapse:collapse;margin:18px 0 22px;font:10pt/1.3 Arial}.mf-property-amounts th,.mf-property-amounts td{border:1px solid #111;padding:7px 4px;overflow-wrap:anywhere;text-align:center}.mf-property-amounts th{font-weight:bold}.mf-property-amounts td{height:12mm}.mf-property-sign-pair{display:grid;grid-template-columns:1fr 1fr;gap:8mm;break-inside:avoid}.mf-property-sign-pair>div{min-width:0}.mf-property-sign-pair .mf-property-ttd{margin-top:0}.mf-property-form-settings{margin-top:18px;border-top:1px solid #ccd8e8;padding-top:12px}.mf-property-form-settings summary{font-weight:bold;cursor:pointer}.mf-property-help{font:12px/1.5 Arial;color:#64748b}
`;
function render(type,values){
 const v=k=>esc(values[k]||'................').replace(/\n/g,'<br>');
 const dt=k=>values[k]?esc(new Date(values[k]+'T12:00:00').toLocaleDateString('id-ID',{day:'numeric',month:'long',year:'numeric'})):'................';
 const info=rows=>'<table class="mf-property-data"><tbody>'+rows.map(([label,value])=>'<tr><td>'+esc(label)+'</td><td>:</td><td>'+value+'</td></tr>').join('')+'</tbody></table>';
 const sign=(second=false)=>{const s=second?'2':'';const image=!second&&values.pejabat==='Deki Elanda Pradikta'&&window.ADVIS_SIGNATURE_BASE64;return '<div class="mf-property-ttd"><div>'+v('bankTtd'+s)+'<br>'+v('unitTtd'+s)+'</div><div class="mf-property-ink">'+(image?'<img alt="Tanda tangan sesuai template" src="'+esc(image)+'">':'')+'</div><u><b>'+v('pejabat'+s)+'</b></u><br>'+v('jabatan'+s)+'</div>';};
 const logo=type==='htel'||type==='angsuran'?logos.classic:logos.branch;
 let content='';
 const cert=()=> 'Sertifikat '+v('jenisSertifikat')+' No. '+v('sertifikat')+'/'+v('wilayahSertifikat')+' An '+v('pemilik');
 const to=type==='stnk'?'':'<div class="mf-property-to">Kepada'+(type==='roya'?',':' :')+'<br><b>'+v('tujuan')+'</b><br>Di<br><b>'+v('kotaTujuan')+'</b></div>';
 const subject=text=>'<div class="mf-property-subject"><div>Perihal</div><div>:</div><div>'+text+'</div></div>';
 if(type==='htel')content=subject('Permohonan Pendaftaran Hak Tanggungan '+v('peringkat')+' Debitur An. '+v('nama')+'.')+'<p>Menunjuk perihal diatas, dengan ini kami lampirkan berkas pengurusan pendaftaran Hak Tanggungan Peringkat '+v('peringkat')+' guna kepentingan “PT. Bank Mandiri (Persero) Tbk.” dengan data sebagai berikut :</p><ol class="mf-property-list"><li>Asli Sertipikat '+v('jenisSertifikat')+' No. '+v('sertifikat')+'/'+v('wilayahSertifikat')+', an. '+v('pemilik')+'.</li><li>Akta Pemberian Hak Tanggungan Nomor: '+v('akta')+' Tanggal '+dt('tanggalAkta')+'.</li><li>Surat Pengantar PPAT</li><li>Data-data para pihak</li></ol><p>Demikian kami sampaikan, atas perhatiannya kami ucapkan terima kasih.</p>'+sign();
 if(type==='roya'){const property=cert()+' yang terletak di '+v('lokasi');const ht='Hak Tanggungan Peringkat '+v('peringkat')+' No. '+v('ht')+' tanggal '+dt('tanggalHt');content=subject('Peroyaan Hak Tanggungan '+property+'.')+'<p>Dengan ini kami mohon bantuan Saudara untuk melaksanakan peroyaan '+ht+' yang mengikat '+property+'. Sertifikat tersebut sudah tidak menjadi agunan pada Bank kami.</p><p>Terlampir kami sampaikan asli dokumen sebagai berikut :</p><ol class="mf-property-list"><li>Asli '+property+'.</li><li>Asli Sertifikat '+ht+'.</li></ol><p>Demikian kami sampaikan. Atas perhatian dan kerjasamanya, kami ucapkan terima kasih.</p>'+sign();}
 if(type==='stnk')content='<h1 class="mf-property-title">SURAT KETERANGAN</h1>'+subject('BPKB yang Dijaminkan')+'<p>Menunjuk perihal tersebut diatas, menerangkan bahwa :</p>'+info([['No. BPKB',v('bpkb')],['Nama dalam BPKB',v('nama')],['Alamat',v('alamat')],['No Rangka/NIK',v('rangka')],['No Mesin',v('mesin')],['No.Pol dalam BPKB',v('polisi')]])+'<p>Merupakan jaminan di PT Bank Mandiri (Persero) Tbk.</p><p>Surat Keterangan ini dikeluarkan atas permintaan yang bersangkutan.</p><p>Demikian kami sampaikan agar dapat dipergunakan sesuai kebutuhan.</p>'+sign();
 if(type==='angsuran')content=subject('<b>Permohonan Penyesuaian Angsuran Debitur</b>')+'<p>Sehubungan dengan adanya ketidaksesuaian tagihan angsuran (jumlah tagihan pokok dan bunga) Debitur kami pasca dilakukan restrukturisasi kredit Nota No. '+v('nota')+' tanggal '+dt('tanggalNota')+', maka dengan ini kami mohon bantuannya untuk melakukan penyesuaian tagihan Debitur kami dengan data sebagai berikut :</p>'+info([['Nama Debitur',v('nama')],['No Rekening Pinjaman',v('rekening')],['No Rekening Tabungan (AGF)',v('agf')]])+'<table class="mf-property-amounts"><thead><tr>'+['Periode','Angsuran Pokok (Rp.)','Angsuran Bunga (Rp.)','TBYD (Rp)','BYDT (Rp)','Jumlah Angsuran (Rp.)'].map(t=>'<th>'+t+'</th>').join('')+'</tr></thead><tbody><tr>'+['periode','pokok','bunga','tbyd','bydt','jumlah'].map(k=>'<td>'+v(k)+'</td>').join('')+'</tr></tbody></table><p>Demikian kami sampaikan, atas bantuan dan kerjasamanya kami ucapkan terima kasih.</p><p>Menyetujui,</p><div class="mf-property-sign-pair">'+sign()+sign(true)+'</div>';
 return '<div class="mf-document"><article class="mf-page mf-property mf-property-'+type+'"><div class="mf-property-head"><div class="mf-property-meta"><table><tbody><tr><td>Nomor</td><td>:</td><td>'+v('nomor')+'</td></tr><tr><td>Tanggal</td><td>:</td><td>'+dt('tanggal')+'</td></tr><tr><td>Lampiran</td><td>:</td><td>'+v('lampiran')+'</td></tr></tbody></table></div><div class="mf-property-brand"><img src="'+logo+'" alt="Bank Mandiri"><b>'+v('bank')+'</b><br>'+v('cabang')+'<br>'+v('alamatKop')+'</div></div>'+to+content+'</article></div>';
}
function setup(type){const root=document.getElementById('mfFields');const details=document.createElement('details');details.className='mf-property-form-settings';details.innerHTML='<summary>Kop dan penanda tangan sesuai template</summary><p class="mf-property-help">Terisi sesuai file Word. Buka bagian ini bila perlu mengubah kop, nama, atau jabatan. Gambar tanda tangan hanya tampil untuk nama penanda tangan yang sesuai.</p>';for(const [key] of [...settings,...(type==='angsuran'?definitions.angsuran.fields.filter(f=>f[0].endsWith('2')):[])]){const input=document.getElementById('mf_'+key);if(input)details.append(input.previousElementSibling,input);}root.append(details);}
const logos={"classic": "data:image/jpeg;base64,", "branch": "data:image/jpeg;base64,"};
window.ManualPropertyTemplates={definitions,defaults,css,render,setup};
})();
